package pe.com.dentalamericana.finance;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;@Entity@Table(name="gastos")public class Expense{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="sesion_caja_id",nullable=false)private Long cashSessionId;@Column(nullable=false)private String categoria;@Column(nullable=false)private String descripcion;private String proveedor;@Column(name="documento_referencia")private String documentReference;@Column(name="metodo_pago_id",nullable=false)private Long paymentMethodId;@Column(nullable=false)private BigDecimal monto;@Enumerated(EnumType.STRING)@Column(nullable=false)private FinancialRecordStatus estado;@Column(name="registrado_por",nullable=false)private Long registeredBy;@Column(name="confirmado_por",nullable=false)private Long confirmedBy;@Column(name="registrado_en",nullable=false,updatable=false)private Instant registeredAt;@Version private Long version;protected Expense(){}public Expense(Long session,String category,String description,String provider,String document,Long method,BigDecimal amount,Long actor){cashSessionId=session;categoria=category;descripcion=description;proveedor=provider;documentReference=document;paymentMethodId=method;monto=amount;estado=FinancialRecordStatus.REGISTRADO;registeredBy=actor;confirmedBy=actor;}@PrePersist void create(){registeredAt=Instant.now();}public Long getId(){return id;}public Long getCashSessionId(){return cashSessionId;}public String getCategory(){return categoria;}public String getDescription(){return descripcion;}public String getProvider(){return proveedor;}public String getDocumentReference(){return documentReference;}public Long getPaymentMethodId(){return paymentMethodId;}public BigDecimal getAmount(){return monto;}public FinancialRecordStatus getStatus(){return estado;}public Instant getRegisteredAt(){return registeredAt;}public Long getVersion(){return version;}}
